func fetch(ctx context.Context) (string, error) {
	ch := make(chan string)
	go func() {
		ch <- slowCall()
	}()

	select {
	case r := <-ch:
		return r, nil
	case <-ctx.Done():
		return "", ctx.Err()
	}
}

