import (
	"fmt"
	"strconv"
)

func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, 0, len(s))
	for _, v := range s {
		out = append(out, f(v))
	}
	return out
}

func main() {
	sq := Map([]int{1, 2, 3}, func(n int) string { return strconv.Itoa(n * n) })
	fmt.Println(sq, len(sq))
}

